#[test]
fn test_initial_state_is_normal() {
    let detector = DriftDetector::new(DriftDetectorConfig::default());
    assert_eq!(detector.state(), DriftState::Normal, "New detector must start in Normal state");
}

#[test]
fn test_state_transition_normal_to_warning() {
    let cfg = DriftDetectorConfig {
        target_mean: 0.0,
        epsilon: 0.1,
        threshold: 5.0,
        min_observations: 10,
    };
    let mut detector = DriftDetector::new(cfg);

    // Feed 10 observations with consistent positive drift (value = 1.0)
    for _ in 0..10 {
        detector.update(1.0);
    }

    // After 10 obs, S_high = 10 * (1.0 - 0.0 - 0.1) = 9.0 > threshold 5.0
    // But min_observations = 10, so drift should be signaled
    assert_eq!(
        detector.state(),
        DriftState::Drift,
        "Consistent drift past min_observations must trigger Drift state"
    );
}

#[test]
fn test_state_transition_normal_to_warning_threshold_not_reached() {
    let cfg = DriftDetectorConfig {
        target_mean: 0.0,
        epsilon: 0.5,
        threshold: 10.0,
        min_observations: 5,
    };
    let mut detector = DriftDetector::new(cfg);

    // Feed 5 observations with small drift (value = 0.6)
    // S_high = 5 * (0.6 - 0.0 - 0.5) = 0.5 < 10.0
    for _ in 0..5 {
        detector.update(0.6);
    }

    assert_eq!(
        detector.state(),
        DriftState::Normal,
        "Small drift below threshold must remain Normal"
    );
}

#[test]
fn test_warning_state_emitted_before_drift() {
    let cfg = DriftDetectorConfig {
        target_mean: 0.0,
        epsilon: 0.1,
        threshold: 5.0,
        min_observations: 0, // Allow immediate signaling
    };
    let mut detector = DriftDetector::new(cfg);

    // Feed values that push S_high to exactly 5.0
    // Each update adds (1.0 - 0.0 - 0.1) = 0.9
    // Need 5.0 / 0.9 ≈ 5.56 → 6 updates to exceed
    for _ in 0..5 {
        detector.update(1.0);
        assert_eq!(
            detector.state(),
            DriftState::Normal,
            "Before threshold, state must be Normal"
        );
    }

    // 6th update should cross threshold
    detector.update(1.0);
    assert_eq!(
        detector.state(),
        DriftState::Drift,
        "Crossing threshold must trigger Drift"
    );
}

