#[test]
fn test_cusum_high_accumulation_math() {
    let cfg = DriftDetectorConfig {
        target_mean: 10.0,
        epsilon: 0.5,
        threshold: 100.0,
        min_observations: 0,
    };
    let mut detector = DriftDetector::new(cfg);

    // Feed value 12.0 → deviation = 12.0 - 10.0 - 0.5 = 1.5
    detector.update(12.0);
    assert_eq!(detector.s_high(), 1.5, "S_high must accumulate exactly 1.5");
    assert_eq!(detector.s_low(), 0.0, "S_low must remain 0 for positive drift");

    // Feed value 11.0 → deviation = 11.0 - 10.0 - 0.5 = 0.5
    detector.update(11.0);
    assert_eq!(detector.s_high(), 2.0, "S_high must accumulate to 2.0");
    assert_eq!(detector.s_low(), 0.0, "S_low must remain 0");

    // Feed value 9.0 → deviation = 9.0 - 10.0 - 0.5 = -1.5 → S_high += -1.5 = 0.5
    detector.update(9.0);
    assert_eq!(detector.s_high(), 0.5, "S_high must decrease but not go negative");
    assert_eq!(detector.s_low(), 0.0, "S_low must remain 0");
}

#[test]
fn test_cusum_low_accumulation_math() {
    let cfg = DriftDetectorConfig {
        target_mean: 10.0,
        epsilon: 0.5,
        threshold: 100.0,
        min_observations: 0,
    };
    let mut detector = DriftDetector::new(cfg);

    // Feed value 8.0 → deviation = 8.0 - 10.0 - 0.5 = -2.5 → S_low += 2.5
    detector.update(8.0);
    assert_eq!(detector.s_low(), 2.5, "S_low must accumulate exactly 2.5");
    assert_eq!(detector.s_high(), 0.0, "S_high must remain 0 for negative drift");

    // Feed value 9.0 → deviation = 9.0 - 10.0 - 0.5 = -1.5 → S_low += 1.5 = 4.0
    detector.update(9.0);
    assert_eq!(detector.s_low(), 4.0, "S_low must accumulate to 4.0");
    assert_eq!(detector.s_high(), 0.0, "S_high must remain 0");
}

#[test]
fn test_cusum_reset_on_noise() {
    let cfg = DriftDetectorConfig {
        target_mean: 0.0,
        epsilon: 0.5,
        threshold: 100.0,
        min_observations: 0,
    };
    let mut detector = DriftDetector::new(cfg);

    // Positive drift
    detector.update(1.0); // S_high = 0.5
    detector.update(1.0); // S_high = 1.0

    // Negative drift cancels out
    detector.update(-1.0); // S_high = max(0, 1.0 + (-1.0 - 0.0 - 0.5)) = max(0, -0.5) = 0
    assert_eq!(detector.s_high(), 0.0, "S_high must reset to 0 when deviation is negative");
    assert_eq!(detector.s_low(), 0.5, "S_low must accumulate the negative deviation");
}

