#[test]
fn test_min_observations_gate() {
    let cfg = DriftDetectorConfig {
        target_mean: 0.0,
        epsilon: 0.1,
        threshold: 1.0,
        min_observations: 100,
    };
    let mut detector = DriftDetector::new(cfg);

    // Even with massive drift, state must remain Normal until 100 observations
    for _ in 0..99 {
        detector.update(100.0);
        assert_eq!(
            detector.state(),
            DriftState::Normal,
            "Drift must be suppressed before min_observations"
        );
    }

    // 100th observation unlocks drift detection
    detector.update(100.0);
    assert_eq!(
        detector.state(),
        DriftState::Drift,
        "Drift must be signaled after min_observations reached"
    );
}

#[test]
fn test_zero_epsilon_edge() {
    let cfg = DriftDetectorConfig {
        target_mean: 0.0,
        epsilon: 0.0,
        threshold: 1.0,
        min_observations: 0,
    };
    let mut detector = DriftDetector::new(cfg);

    // Any deviation from mean accumulates
    detector.update(0.5); // S_high = 0.5
    assert_eq!(detector.s_high(), 0.5);
    detector.update(0.5); // S_high = 1.0 → threshold reached
    assert_eq!(
        detector.state(),
        DriftState::Drift,
        "Zero epsilon must make detector maximally sensitive"
    );
}

