#[test]
fn test_s_values_never_negative() {
    let cfg = DriftDetectorConfig::default();
    let mut detector = DriftDetector::new(cfg);

    // Feed 1000 random-ish values (deterministic sequence)
    let mut seed = 42u64;
    for i in 0..1000 {
        seed = seed.wrapping_mul(6364136223846793005).wrapping_add(1442695040888963407);
        let value = ((seed >> 33) as f64 / (u32::MAX as f64)) * 20.0 - 10.0;
        detector.update(value);
        assert!(
            detector.s_high() >= 0.0 && detector.s_low() >= 0.0,
            "S_high and S_low must never be negative (iteration {})",
            i
        );
    }
}

#[test]
fn test_state_never_regresses_from_drift() {
    let cfg = DriftDetectorConfig {
        target_mean: 0.0,
        epsilon: 0.1,
        threshold: 5.0,
        min_observations: 0,
    };
    let mut detector = DriftDetector::new(cfg);

    // Force drift
    for _ in 0..10 {
        detector.update(1.0);
    }
    assert_eq!(detector.state(), DriftState::Drift);

    // Even with perfect data afterward, state must remain Drift (latching)
    for _ in 0..100 {
        detector.update(0.0);
    }
    assert_eq!(
        detector.state(),
        DriftState::Drift,
        "Drift state must be latched once triggered"
    );
}

#[test]
fn test_deterministic_behavior() {
    let cfg = DriftDetectorConfig::default();
    let mut d1 = DriftDetector::new(cfg);
    let mut d2 = DriftDetector::new(cfg);

    let data: [f64; 50] = core::array::from_fn(|i| (i as f64 * 0.37).sin() * 2.0);

    for &v in &data {
        d1.update(v);
        d2.update(v);
    }

    assert_eq!(d1.s_high(), d2.s_high(), "S_high must be deterministic");
    assert_eq!(d1.s_low(), d2.s_low(), "S_low must be deterministic");
    assert_eq!(d1.state(), d2.state(), "State must be deterministic");
}

// ============================================================================
// INTEGRATION TEST: Realistic drift scenario
// ============================================================================

#[test]
fn test_realistic_drift_detection() {
    let cfg = DriftDetectorConfig {
        target_mean: 50.0,
        epsilon: 2.0,
        threshold: 20.0,
        min_observations: 50,
    };
    let mut detector = DriftDetector::new(cfg);

    // Phase 1: Stable data around mean (50 ± 1)
    for _ in 0..100 {
        detector.update(50.0 + (rand_simple() - 0.5) * 2.0);
    }
    assert_eq!(
        detector.state(),
        DriftState::Normal,
        "Stable data must not trigger drift"
    );

    // Phase 2: Gradual drift upward
    for i in 0..100 {
        let drift_amount = (i as f64) * 0.1; // 0.0 → 9.9
        detector.update(50.0 + drift_amount);
    }

    // Phase 3: Sustained high values
    for _ in 0..50 {
        detector.update(60.0);
    }

    assert_eq!(
        detector.state(),
        DriftState::Drift,
        "Sustained upward drift must eventually trigger alarm"
    );
}

/// Simple deterministic PRNG for test reproducibility
fn rand_simple() -> f64 {
    // LCG with fixed seed for deterministic tests
    static mut SEED: u64 = 0x853c49e6748fea9b;
    unsafe {
        SEED = SEED.wrapping_mul(6364136223846793005).wrapping_add(1442695040888963407);
        ((SEED >> 33) as f64) / (u32::MAX as f64)
    }
}

// ============================================================================
// PERFORMANCE SANITY TEST
// ============================================================================

#[test]
fn test_high_volume_throughput() {
    let cfg = DriftDetectorConfig::default();
    let mut detector = DriftDetector::new(cfg);

    // 1M updates should complete quickly and maintain O(1) memory
    let start = std::time::Instant::now();
    for i in 0..1_000_000 {
        detector.update((i as f64 % 100.0) - 50.0);
    }
    let elapsed = start.elapsed();

    assert!(
        elapsed.as_secs() < 5,
        "1M updates should complete in under 5 seconds (took {:?})",
        elapsed
    );
    assert!(
        detector.s_high().is_finite() && detector.s_low().is_finite(),
        "State must remain finite after 1M updates"
    );
}